package com.mcnex.conversation;
import android.app.*;import android.os.*;import android.view.*;import org.json.*;
public class DetailSwipeProbe extends Instrumentation {
 public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){JSONObject report=new JSONObject();try{JSONArray list=MeetingManager.get(getTargetContext()).list();if(list.length()==0)throw new Exception("No existing meeting to view");String id=list.getJSONObject(0).getString("id");MainActivity a=(MainActivity)startActivitySync(new android.content.Intent(getTargetContext(),MainActivity.class).addFlags(android.content.Intent.FLAG_ACTIVITY_NEW_TASK));Thread.sleep(500);runOnMainSync(()->a.detail(id,0));Thread.sleep(400);runOnMainSync(()->a.switchDetail(1));Thread.sleep(600);runOnMainSync(()->{try{java.lang.reflect.Field field=MainActivity.class.getDeclaredField("minutesWeb");field.setAccessible(true);View web=(View)field.get(a);if(web==null||web.getHeight()<100)throw new IllegalStateException("Reader not visible");ViewGroup content=a.findViewById(android.R.id.content);if(content.getChildCount()!=1)throw new IllegalStateException("Overlay left behind");long t=SystemClock.uptimeMillis();a.dispatchTouchEvent(MotionEvent.obtain(t,t,MotionEvent.ACTION_DOWN,100,260,0));a.dispatchTouchEvent(MotionEvent.obtain(t,t+50,MotionEvent.ACTION_MOVE,900,260,0));a.dispatchTouchEvent(MotionEvent.obtain(t,t+100,MotionEvent.ACTION_UP,900,260,0));}catch(Exception e){throw new RuntimeException(e);}});Thread.sleep(500);runOnMainSync(()->{try{java.lang.reflect.Field field=MainActivity.class.getDeclaredField("detailTab");field.setAccessible(true);if(field.getInt(a)!=0)throw new IllegalStateException("Transcript swipe failed");}catch(Exception e){throw new RuntimeException(e);}});report.put("tabTransition",true).put("swipeBack",true).put("documentHeight",true).put("ok",true);}catch(Throwable e){try{report.put("ok",false).put("error",e.toString());}catch(Exception ignored){}}try(java.io.FileOutputStream f=getTargetContext().openFileOutput("detail-swipe-probe.json",0)){f.write(report.toString().getBytes("UTF-8"));}catch(Exception ignored){}Bundle b=new Bundle();b.putString("report",report.toString());finish(report.optBoolean("ok")?-1:0,b);}
}
